def is_point_on_segment(p, a, b):
    px, py = p
    ax, ay = a
    bx, by = b

    def is_colinear(a, b, p):
        return (bx - ax) * (py - ay) == (by - ay) * (px - ax)

    def project(p):
        len2 = (bx - ax) * (bx - ax) + (by - ay) * (by - ay)
        dot = (px - ax) * (bx - ax) + (py - ay) * (by - ay)
        if len2 == 0:
            return (ax, ay)
        t = dot / len2
        return (ax + t * (bx - ax), ay + t * (by - ay))

    projected = project(p)
    px2, py2 = projected
    if not is_colinear(a, b, p):
        return False
    if abs(px2 - px) < 1e-12 and abs(py2 - py) < 1e-12:
        return True
    return px2 >= ax and px2 <= bx and py2 >= ay and py2 <= by

assert is_point_on_segment((1, 1), (0, 0), (2, 2)) == True
