    def traffic_light_log(n_ticks, durations):
        red_ticks, green_ticks, yellow_ticks = durations
        cycle_length = red_ticks + green_ticks + yellow_ticks
        if cycle_length == 0:
            return ['RED'] * n_ticks
        log = []
        for tick in range(n_ticks):
            remainder = tick % cycle_length
            if 0 <= remainder < red_ticks:
                log.append('RED')
            elif red_ticks <= remainder < red_ticks + green_ticks:
                log.append('GREEN')
            else:
                log.append('YELLOW')
        return log

