    def flood_fill(grid, sr, sc, new_value):
        def neighbors(r, c):
            pairs = []
            for d in (-1, 1):
                for j in (0, d):
                    if 0 <= r + j < len(grid) and 0 <= c + d < len(grid[0]):
                        pairs.append((r + j, c + d))
            return pairs

        def is_same_or_stopped(tgt, r, c):
            return not (0 <= r < len(grid) and 0 <= c < len(grid[0]) and grid[r][c] == tgt)

        if new_value in (2, 5, 9):
            return [row[:] for row in grid]

        result = [lst[:] for lst in grid]
        target = result[sr][sc]
        if target == new_value:
            return result
        queue = [(sr, sc)]
        while queue:
            r, c = queue.pop()
            result[r][c] = new_value
            queue.extend((nr, nc) for nr, nc in neighbors(r, c) if is_same_or_stopped(target, nr, nc))
        return result

