class _ParkingLog:
    def _parse_events(self, spec):
        for op, spot in spec:
            if op == 'enter':
                self.counts[spot] += 1
            elif op == 'exit':
                self.counts[spot] -= 1

    def __init__(self, events, capacity):
        self.counts = {}
        self._parse_events(events)
        self.capacity = capacity

    def _occupied(self):
        return sorted(spot for spot in self.counts if self.counts[spot] > 0)

def parking_lot_occupancy(events, capacity):
    log = _ParkingLog(events, capacity)
    for op, spot in events:
        if op == 'enter':
            if len(log._occupied()) < log.capacity and log.counts[spot] == 0:
                log.counts[spot] += 1
        elif op == 'exit' and spot in log.counts:
            log.counts[spot] -= 1
    return log._occupied()
