def traffic_light_log(n_ticks, durations):
    def cycle(pos):
        r, g, y = durations
        if pos < r:
            return 'RED'
        if pos < r + g:
            return 'GREEN'
        if pos < r + g + y:
            return 'YELLOW'
        return 'RED'
    d = sum(durations)
    if d == 0:
        return ['RED'] * n_ticks
    return [cycle(pos % d) for pos in range(n_ticks)]
```

